import React from "react";
import { useNavigate } from "react-router-dom";
import "./HomePage.css";

function HomePage() {
  const navigate = useNavigate();

  const menuItems = [
    { name: "Home", action: () => navigate("/") },
    { name: "Profile", action: () => navigate("/profile") },
    { name: "Bookings", action: () => navigate("/booking") },
    { name: "Payment", action: () => navigate("/payment") },
    { name: "Success", action: () => navigate("/success") },
  ];

  return (
    <div className="homepage-container">
      {/* Navbar */}
      <nav className="navbar">
        <div className="navbar-logo">Parking Slot System</div>
        <div className="navbar-links">
          {menuItems.map((item, index) => (
            <button key={index} className="nav-btn" onClick={item.action}>
              {item.name}
            </button>
          ))}
          <button
            className="logout-btn"
            onClick={() => {
              localStorage.removeItem("user");
              navigate("/login");
            }}
          >
            Logout
          </button>
        </div>
      </nav>

      {/* Main Content */}
      <main className="main-content">
        <div className="welcome-card">
          <h1>Welcome!</h1>
          <p>
            Book your parking slots easily and quickly. Use the navbar above
            to navigate through the system.
          </p>
          <button className="start-btn" onClick={() => navigate("/booking")}>
            Start Booking
          </button>
        </div>
      </main>
    </div>
  );
}

export default HomePage;
